KG42.register("rules-e0550b3d567a4ffeb275343e",{"id":"28-multiclass_prosumer_preferences::v141-c-R007","paper":"28-multiclass_prosumer_preferences","record":{"rule_id":"v141-c-R007","mechanism_id":"v141-a-M01","name":"Consumer participation","process_stage":"participation","market_meaning":"The energy classes a prosumer is permitted to use to supply its loads are specified by its individual allowed class set. Scope: General multiclass P2P market formulation: prosumers acting as energy demanders. Only low-income households are allowed to use subsidised energy. Scope: IEEE European Low Voltage Test Feeder case study with 55 prosumers. Condition: Use of subsidised energy in the case study.","independence_rationale":"Relations governed by the approved function participation.consumer under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["participation.consumer"],"E":[],"omega":{"market_type":"LEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"participation","context_text":"General multiclass P2P market formulation: prosumers acting as energy demanders. | IEEE European Low Voltage Test Feeder case study with 55 prosumers.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-G01-E20","v141-b-g02-e027"]},"x":[{"variable_id":"v141-c-R007-x-zik","symbol":"z_{ik}^{(t)}","meaning":"Average allocated load power of energy class k to prosumer i at interval t, as used in the source load constraint whose class sum is restricted to K_i.","kind":"operational","domain":"\\mathbb{R}_{\\ge 0}","unit":null,"indices":["i","k","t"],"evidence_ids":["v141-b-G01-E20"]},{"variable_id":"v141-c-R007-x-zig","symbol":"z_{ig}^{(t)}","meaning":"Average allocated load power from grid-class energy to prosumer i at interval t, as used in the source load constraint whose class sum is restricted to K_i.","kind":"operational","domain":"\\mathbb{R}_{\\ge 0}","unit":null,"indices":["i","t"],"evidence_ids":["v141-b-G01-E20"]}],"theta":[{"parameter_id":"v141-c-R007-theta-K_i","symbol":"\\mathcal{K}_i","meaning":"Individual set of energy classes that prosumer i is allowed to use to supply its loads; the source states \\mathcal{K}_i \\subseteq \\mathcal{K}.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i"],"evidence_ids":["v141-b-G01-E20"]},{"parameter_id":"v141-c-R007-theta-K","symbol":"\\mathcal{K}","meaning":"Ambient set of energy classes generated by prosumers, defined in the source as \\mathcal{K}=\\{1,\\ldots,K\\} and used to state \\mathcal{K}_i \\subseteq \\mathcal{K}.","value":{"kind":"symbolic","number_value":null,"text_value":"\\{1,\\ldots,K\\}"},"unit":null,"indices":[],"evidence_ids":["v141-b-G01-E13","v141-b-G01-E20"]},{"parameter_id":"v141-c-R007-theta-T","symbol":"\\mathcal{T}","meaning":"MPC time horizon defined in the source as \\mathcal{T}=\\{t_0,\\ldots,T\\}, used as the quantifier scope in the load constraint.","value":{"kind":"symbolic","number_value":null,"text_value":"\\{t_0,\\ldots,T\\}"},"unit":null,"indices":[],"evidence_ids":["v141-b-G01-E13","v141-b-G01-E20"]},{"parameter_id":"v141-c-R007-theta-zpred","symbol":"z_i^{pred(t)}","meaning":"Predicted load power for prosumer i at interval t; the supplied source does not state a unit for this quantity.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["i","t"],"evidence_ids":["v141-b-G01-E20"]}],"phi":[{"constraint_id":"v141-c-R007-C001","kind":"procedural","role":"core","statement":"The energy classes a prosumer is permitted to use to supply its loads are specified by its individual allowed class set. Scope: General multiclass P2P market formulation: prosumers acting as energy demanders.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["participation.consumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-G01-E20"]},{"constraint_id":"v141-c-R007-C002","kind":"procedural","role":"core","statement":"Only low-income households are allowed to use subsidised energy. Scope: IEEE European Low Voltage Test Feeder case study with 55 prosumers. Condition: Use of subsidised energy in the case study.","expression":null,"formalization_origin":"not_formalized","template_id":null,"members":["participation.consumer"],"variable_refs":[],"parameter_refs":[],"evidence_ids":["v141-b-g02-e027"]},{"constraint_id":"v141-c-R007-C003","kind":"mathematical","role":"core","statement":"Source equations (7)-(8) restrict the load-service class sum to prosumer i's individual allowed class set K_i, require total allocated class and grid load power to equal predicted load, and require nonnegative allocated class and grid load powers. Scope: General multiclass P2P market formulation: prosumers acting as energy demanders.","expression":"\\mathcal{K}_i \\subseteq \\mathcal{K},\\quad \\sum_{k\\in\\mathcal{K}_i} z_{ik}^{(t)} + z_{ig}^{(t)} = z_i^{pred(t)},\\ \\forall t\\in\\mathcal{T},\\quad 0 \\le z_{ig}^{(t)},\\ 0 \\le z_{ik}^{(t)},\\ \\forall k\\in\\mathcal{K},\\ \\forall t\\in\\mathcal{T}.","formalization_origin":"source","template_id":null,"members":["participation.consumer"],"variable_refs":["v141-c-R007-x-zik","v141-c-R007-x-zig"],"parameter_refs":["v141-c-R007-theta-K_i","v141-c-R007-theta-K","v141-c-R007-theta-T","v141-c-R007-theta-zpred"],"evidence_ids":["v141-b-G01-E20","v141-b-G01-E13"]}],"pi":[{"evidence_id":"v141-b-G01-E20","location":{"location_id":"src-96285c344a-p04-c2r1__v141-a-M01-clearing","page":4,"printed_page":null,"section":"III. Multi-class Energy Management","anchor_text":"IEEE TRANSACTIONS ON POWER SYSTEMS, VOL. 34, NO. 5, SEPTEMBER 2019 reserved for low-income household","equation_id":"(7)-(8)","figure_id":null,"table_id":null,"image_ref":"pages/page-04.png","occurrence_role":"formula"},"source_text":"Also, each prosumer, i \\in \\mathcal{N}, has load constraints, renewable generation constraints and battery constraints. The prosumer load constraints require that the total power allocated to its load meets its load predictions, z_i^{pred(t)}, \\forall t \\in \\mathcal{T}. Let \\mathcal{K}_i \\subseteq \\mathcal{K} be the set of energy classes that prosumer i is allowed to use to supply its loads (e.g., in the example from Fig. 1, subsidised energy is reserved for low-income households). \\sum_{k \\in \\mathcal{K}_i} z_{ik}^{(t)} + z_{ig}^{(t)} = z_i^{pred(t)}, \\forall t \\in \\mathcal{T}. \\quad 0 \\le z_{ig}^{(t)}, 0 \\le z_{ik}^{(t)}, \\forall k \\in \\mathcal{K}, \\forall t \\in \\mathcal{T}."},{"evidence_id":"v141-b-g02-e027","location":{"location_id":"src-96285c344a-p06-c2r3__v141-a-M01-participation","page":6,"printed_page":null,"section":"V. Results","anchor_text":"and average resistance between the prosumers and main grid of Rg = 0.084Ω are used. t.) There are th","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-06.png","occurrence_role":"example"},"source_text":"The operation of the proposed P2P energy market platform based on multi-class energy management was verified using the IEEE European Low Voltage Test Feeder [42], with 55 prosumers. ... There are three types of prosumers in the distribution network, ‘green prosumers’, ‘philanthropic prosumers’ and ‘low-income households’. Based on their preferences, three energy classes are introduced; ‘grid energy’, ‘green energy’ and ‘subsidised energy’. Grid energy, is traded with the wholesale market at five minute trading intervals through the platform agent. Green energy is traded at a premium, so it is allowed to be substituted for and stored/sold as grid energy. Only low-income households are allowed to use subsidised energy."},{"evidence_id":"v141-b-G01-E13","location":{"location_id":"src-96285c344a-p03-c2r2__v141-a-M01-clearing","page":3,"printed_page":null,"section":"III. Multi-class Energy Management","anchor_text":"III. MULTI-CLASS ENERGY MANAGEMENT Let the set of distribution network prosumers be N = i- {1, . . .","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-03.png","occurrence_role":"definition"},"source_text":"Let the set of distribution network prosumers be \\mathcal{N} = \\{1, \\ldots, N\\} and the set of energy classes generated by the prosumers be \\mathcal{K} = \\{1, \\ldots, K\\}. The MPC time horizon is \\mathcal{T} = \\{t_0, \\ldots, T\\}, where t_0 is the current trading interval. Each time interval t \\in \\mathcal{T} has its own duration T_s^{(t)}."}],"field_notes":{"empty_E_reason":"C explicitly supplied only source-backed unary facts for this function; other graph gaps remain reviewable.","empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-participation","v141-a-M01-pricing"],"extras":{"decision_anchor":"participation.consumer","graph_fact_supports":[[{"evidence_id":"v141-b-G01-E20","quote":"the set of energy classes that prosumer i is allowed to use to supply its loads"}],[{"evidence_id":"v141-b-g02-e027","quote":"Only low-income households are allowed to use subsidised energy."}]],"C2_formalization":{"graph_sha256":"a092e0db1012130010eae799c0c3b698ca48af53df4f5490d9aa30e490ac7d64","applicability":"formalized","reason":"The source explicitly defines the individual allowed energy-class set K_i subset K and equation (7) restricts the load-service class sum to K_i, so the allowed-class permission can be formalized without changing the frozen node set. The low-income/subsidised-energy case-study restriction remains procedural because the supplied evidence does not define formal eligibility symbols for it. Evidence used here is candidate/unreviewed under the experiment; no independent source audit is claimed.","bindings":[{"object_id":"v141-c-R007-x-zik","node_ids":["participation.consumer"],"edge_ids":[],"rationale":"This load-allocation variable appears in the source load constraint whose inner class sum is restricted to the prosumer's allowed class set K_i, which is the frozen participation.consumer relation. The frozen rule has no edges."},{"object_id":"v141-c-R007-x-zig","node_ids":["participation.consumer"],"edge_ids":[],"rationale":"This grid-class load-allocation variable appears on the left-hand side of the source load constraint that uses K_i, so it is bound to the frozen participation.consumer relation. The frozen rule has no edges."},{"object_id":"v141-c-R007-theta-K_i","node_ids":["participation.consumer"],"edge_ids":[],"rationale":"K_i is the individual allowed-class set that defines the consumer participation permission in the source. No separate set node or edge exists in the frozen unary rule."},{"object_id":"v141-c-R007-theta-K","node_ids":["participation.consumer"],"edge_ids":[],"rationale":"The ambient energy-class set K is used only to state the source membership relation K_i subset K in the allowed-class load constraint; it is bound to the frozen participation.consumer relation because no separate set node exists."},{"object_id":"v141-c-R007-theta-T","node_ids":["participation.consumer"],"edge_ids":[],"rationale":"The time horizon supplies the quantifier scope of the source allowed-class load constraint. It is bound to participation.consumer because the frozen rule contains only that node and no edges."},{"object_id":"v141-c-R007-theta-zpred","node_ids":["participation.consumer"],"edge_ids":[],"rationale":"Predicted load is the right-hand side of the source load constraint that uses K_i, so it is retained as a parameter of the formalized consumer-participation load condition."},{"object_id":"v141-c-R007-C003","node_ids":["participation.consumer"],"edge_ids":[],"rationale":"This formalizes the allowed-class permission in C001 via the source's load constraint equations (7)-(8). It uses only the existing participation.consumer node; the frozen rule has no edges."}],"revision_requests":[]}},"quarantined_references":[]}});
